 public function transaction(callable $fn,bool $allowMaintenance=false):mixed {if($this->db->inTransaction())return $fn();$this->db->beginTransaction();try{$this->query("INSERT IGNORE INTO ws_settings(setting_key,value) VALUES('write-lock','0')");$this->query("SELECT value FROM ws_settings WHERE setting_key='write-lock' FOR UPDATE");if(!$allowMaintenance&&$this->setting('upgrade-maintenance',false))throw new ApiException('An upgrade is in progress. Retry after it finishes.',503);$value=$fn();$this->db->commit();return $value;}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function record(string $kind,string $id):?array{$v=$this->query('SELECT payload FROM ws_records WHERE kind=? AND id=?',[$kind,$id])->fetchColumn();return $v===false?null:json_decode($v,true,512,JSON_THROW_ON_ERROR);}
