 public function saveSiteSettings(array $input):array{$s=Validation::siteSettings($input);return $this->transaction(function()use($s){if($this->getSiteSettings()['revision']!==$s['revision'])throw new ApiException('Site görünümü değişti. Güncel sürümü yükleyin.',409);$history=$this->setting('appearance-history',[]);$previous=$this->getSiteSettings();if(!in_array($previous['revision'],array_column($history,'revision'),true))$history[]=array_merge($previous,['savedAt'=>self::now()]);$s['revision']++;$history[]=array_merge($s,['savedAt'=>self::now()]);$this->setSetting('appearance-history',array_slice($history,-100));$this->setSetting('site-settings',$s);$this->audit('site-settings','appearance','theme='.$s['theme']['id'].'; revision='.$s['revision']);return $s;});}
