 public function restoreBackup(mixed $b,bool $dryRun=false):array{Validation::check(is_array($b),'Geçersiz yedek.');$rules=isset($b['admissionRules'])?Admission::validate($b['admissionRules']):null;$settings=isset($b['siteSettings'])?Validation::siteSettings($b['siteSettings']):null;$seo=isset($b['seoSettings'])?SEOSettings::validate($b['seoSettings']):null;Validation::check(($b['version']??null)===1,'Geçersiz yedek.');$records=array_map([Validation::class,'managed'],Validation::items($b['records']??null,'records',100000));$revisions=array_map([Validation::class,'managed'],Validation::items($b['revisions']??null,'revisions',100000));$localization=Translations::validateBackup($b['localization']??null,$records);$growth=Growth::validateBackup($b['growth']??null);$extensions=Extensions::validateBackup($b['extensions']??null);$capabilities=Capabilities::validateBackup($b['capabilities']??null);$observations=StoreObservations::validateBackup($b['storeObservations']??null);$submissions=AppSubmissions::validateBackup($b['appSubmissions']??null);$this->identities($records);$seen=[];foreach($records as $r){$key=$r['kind'].':'.$r['id'];Validation::check(!isset($seen[$key])&&is_int($r['revision']??null)&&$r['revision']>0,'Yinelenen kayıt veya geçersiz revizyon.');$seen[$key]=$r['revision'];}$revkeys=[];foreach($revisions as $r){$key=$r['kind'].':'.$r['id'];$rk=$key.':'.($r['revision']??0);Validation::check(is_int($r['revision']??null)&&$r['revision']>0&&!isset($revkeys[$rk])&&(!isset($seen[$key])||$r['revision']<=$seen[$key]),'Geçersiz veya yinelenen revizyon.');$revkeys[$rk]=true;}$feedback=Validation::items($b['feedback']??null,'feedback',10000);$ids=[];foreach($feedback as $f){Validation::check(is_int($f['id']??null)&&$f['id']>0&&!isset($ids[$f['id']])&&is_string($f['appId']??null)&&is_string($f['field']??null)&&strlen($f['field'])<=80&&is_string($f['message']??null)&&strlen($f['message'])<=2000&&in_array($f['status']??null,['open','resolved','dismissed'],true)&&is_string($f