 Capabilities($this->db,$this))->restoreBackup($capabilities);(new StoreObservations($this->db,$this))->restoreBackup($observations);(new AppSubmissions($this->db,$this,$this->config))->restoreBackup($submissions);(new CatalogQuery($this->db,$this))->rebuild();$this->audit('restore-backup','catalog',(string)count($records));return ['restored'=>count($records)];});}
 public function importRecords(mixed $input,bool $dryRun=true):array{Validation::items($input,'records',100);return $this->transaction(function()use($input,$dryRun){$all=$this->all();$keys=[];foreach($all as $r)$keys[$r['kind'].':'.$r['id']]=true;$errors=[];$records=[];foreach($input as $i=>$raw)try{Validation::check(is_array($raw),'Nesne bekleniyor.');$r=Validation::managed(array_replace($raw,['status'=>'draft','seoApproved'=>false,'publishAt'=>null,'reviewNote'=>'İçe aktarılan taslak','revision'=>0]));$k=$r['kind'].':'.$r['id'];Validation::check(!isset($keys[$k]),'Kimlik zaten var veya yineleniyor.');$keys[$k]=true;$records[]=$r;}catch(\Throwable $e){$errors[]=($i+1).': '.$e->getMessage();}try{$this->identities([...$all,...$records]);}catch(\Throwable $e){$errors[]=$e->getMessage();}if(!$dryRun&&!$errors){foreach($records as $r)$this->write(array_replace($r,['revision'=>1,'updatedAt'=>self::now()]));$this->audit('import','catalog',(string)count($records));}return ['valid'=>!$errors,'errors'=>$errors,'records'=>$records,'imported'=>!$dryRun&&!$errors?count($records):0];});}
